-- =============================================================================
-- Catálogo — importação das BASES DE DUCHE da MUDELAR (Excel do utilizador, folha «Bases Duche»).
-- Base de RH (uetjghdkwbywbftedtth). Ficheiro GERADO por script (gerar_bases_duche.js) a partir do Excel
-- bases.xlsx: as linhas de dados abaixo não se editam à mão — regeneram-se.
-- =============================================================================
--
-- Decisões do utilizador (16/11):
--   * Um produto = modelo + medida + cor + textura: 14328 produtos (as 14328 linhas do Excel, todas distintas).
--   * O SKU antigo do Excel (DBBD0001BL70X70PZ) NÃO se guarda. O SKU é o gerado pelas regras do Catálogo:
--     SIGLA_CAT-SIGLA_SUB-NNNN(modelo)-<atributos pela ordem configurada da Mudelar>, ex. DB-BD-0001-BL-PZ-70X70.
--     O SKU antigo é ambíguo (DBBD0001GR770X70PZ: GR7+70X70 ou GR+770X70): os dados lêem-se do NOME
--     («Base de Duche <MODELO> <Cor> <L>X<C> <TEXTURA>»), e o gerador confere que o SKU antigo bate com o nome.
--   * Modelos (Categoria › Subcategoria › Modelo, 20270118300000): SORTY 0001, STONE PLUS 0002, CACH 0003, MIO 0004,
--     SIDE 0005, SMART 0006, ZEUS 0007, na subcategoria «Bases Duche» de «Duche & Banho».
--   * Grelha fica em branco (o atributo Tipo de grelha não se grava). Premium e Ardesia ficam de fora (não estão no Excel).
--   * As siglas das 18 cores e das 3 texturas na Mudelar passam a ser os códigos do Excel (BL, GR7, …, PZ, LS, PD).
--     Se outra opção do mesmo atributo já tinha esse código, fica com a sugestão seguinte (fn_cat_sigla_opcao_livre)
--     e o NOTICE diz qual. Lido na RH a 16/11: ficam com outra sigla Gris Marengo (GM), Antracite (AN), Nogal (NG),
--     Creme (CR), Bege (BG), CALMA (CL) e Olmo Canada (OC). A Mudelar tem 0 produtos: nenhum SKU existente muda.
--   * A marca só identifica (Duplach). O fornecedor «DUPLACH Group, SAU» é criado na Mudelar se não existir e ligado a
--     cada produto (item_suppliers, preferido, preço de compra = custo).
--
-- Decisões desta migration (a confirmar pelo utilizador):
--   * A cor «Beige» do Excel é a opção «BEIG» que já existe na Cor da Mudelar (vinda da Duplach: está no bloco
--     NEGRO … OLIVA, pela mesma ordem do Excel, entre CREMA e ARENA). Não se cria uma «Beige» ao lado de «BEIG» e de
--     «Bege». Para criar em vez disso, mudar 'BEIG' para 'Beige' na linha BG de _bdm_opcoes (o passo 1 cria as que
--     faltarem, com a sigla do Excel e sem hex).
--   * O modelo 0002 chama-se STONE PLUS, mas no Excel os nomes desses 2988 produtos dizem só «PLUS»
--     («Base de Duche PLUS Blanco 70X70 LISO»): o nome do produto fica o do Excel, o do modelo STONE PLUS.
--   * Estado do produto: 'active', como cat_guardar_produto cria (o Excel diz «Draft»).
--   * Custo = «Preço Compra» do Excel (já líquido: Preço Venda × (1 − Desconto 1)); PVP = «Preço Venda»; IVA 23
--     (product_prices.vat_rate). Desconto 1/2, preços grossista/distribuidor/promo (todos 0 ou vazios) não se gravam.
--   * Como o ecrã grava (cat_guardar_produto + cat_guardar_produto_tabelas + cat_guardar_produto_atributos +
--     cat_guardar_produto_modelo + cat_gerar_sku_produto + cat_ligar_fornecedor_produto), mas SET-BASED: 14 328
--     chamadas numa transação abririam dezenas de milhares de subtransações. O SKU calcula-se ANTES de inserir (a mesma
--     regra de fn_cat_sku_partes, sem provisório), e o bloco de conferir recalcula-o com fn_cat_sku_partes +
--     fn_cat_modelo_numero a partir do que ficou gravado, para TODOS os produtos, e com cat_prever_sku_modelo para 20 ao
--     acaso. products.supplier_id escreve-se logo no INSERT (o gatilho fn_item_suppliers_sync_preferred não tem nada a
--     mudar: poupa 14 328 UPDATE).
--   * AUDITORIA: os INSERT em massa (products, product_organizations, product_prices, product_attribute_values,
--     item_suppliers ≈ 115 000 linhas) correm com app.audit_bypass = 'on' (os quatro gatilhos de auditoria destas
--     tabelas respeitam-no). Sem isso, entity_audit_log (56 MB, ~47 600 linhas lidas a 16/11) receberia ~115 000 linhas
--     (mais do dobro) só com a cópia de cada linha importada. Fica UMA linha consolidada (fn_manual_audit_log, tabela
--     products, entidade = a subcategoria) com os números da importação. As escritas pequenas (siglas das opções,
--     modelos, unidade, fornecedor) ficam auditadas normalmente. Fonte: app.audit_source = 'migration:bases_duche_mudelar'.
--
-- GUARDA (inerte: RAISE NOTICE e sai sem escrever nada) se: a organização 3242e925-… não existir com o nome
-- 'Mudelar'; faltar a versão dos modelos (product_models / fn_cat_modelo_numero / cat_prever_sku_modelo, 20270118300000);
-- não existirem «Duche & Banho» › «Bases Duche» na Mudelar; já houver produtos vivos nessa subcategoria; já houver um
-- produto vivo da Mudelar com um dos nomes do Excel; ou já houver nessa subcategoria um modelo com um dos nomes ou
-- números que não seja exatamente o mesmo (nome e número). Isto também a torna inerte numa segunda execução e na base
-- principal, onde a Mudelar já tem estes produtos (rever antes de juntar o ramo ao main).
-- Falha (RAISE EXCEPTION, nada fica) se faltar o resto da configuração: siglas da categoria/subcategoria, marca Duplach,
-- atributos cor/textura/medida, uma opção ambígua ou desativada, membro para created_by, fornecedor desativado, SKU
-- repetido (diz quais) ou já usado noutro produto da Mudelar.
--
-- Conferir no fim (RAISE EXCEPTION se divergir): 14328 produtos na subcategoria e por modelo como no Excel; 7 modelos;
-- cada produto com Cor, Textura e Medida certas, custo, PVP, fornecedor preferido, marca, unidade; SKUs únicos, no formato
-- e iguais ao recalculado; 20 ao acaso iguais a cat_prever_sku_modelo; as 21 siglas; nenhuma linha de outra organização
-- tem o xmin desta transação (em vez de contar antes/depois, que falharia se alguém estivesse a trabalhar na nike durante
-- o push).
--
-- ORDEM: depois de 20270118300000_catalogo_modelos_e_sku_por_modelo.sql (e de 20270118000000, 20270118200000).
-- Teste: supabase/tests/catalogo_bases_duche_mudelar.test.sql (BEGIN … ROLLBACK, só leitura; o passo 0 falha antes).
-- ATENÇÃO antes do db push: `supabase db push` aplica TUDO o que estiver pendente; listar com
-- `supabase migration list --linked` imediatamente antes.
-- =============================================================================

SET lock_timeout = '5s';
SET statement_timeout = '15min';

DO $mig$
DECLARE
  c_org        constant uuid    := '3242e925-da26-459a-8258-be04d904e355';
  c_fonte      constant text    := 'migration:bases_duche_mudelar';
  c_total      constant integer := 14328;
  c_iva        constant numeric := 23;
  c_cat_nome   constant text    := 'Duche & Banho';
  c_sub_nome   constant text    := 'Bases Duche';
  c_marca_nome constant text    := 'Duplach';
  c_forn_nome  constant text    := 'DUPLACH Group, SAU';
  c_unidade    constant text    := 'un';
  c_amostra    constant integer := 20;
  c_max_modelos_ativos constant integer := 2000;
  c_max_modelos_vivos  constant integer := 10000;
  v_agora   timestamptz := clock_timestamp();
  v_n bigint; v_m bigint; v_k bigint; v_xid text; v_txt text; v_trocas text := ''; v_criadas text := '';
  v_cat uuid; v_sub uuid; v_cat_sigla text; v_sub_sigla text; v_cat_ativa boolean; v_sub_ativa boolean;
  v_marca uuid; v_marca_ativa boolean; v_uom uuid; v_sup uuid; v_sup_ativo boolean; v_sup_criado boolean := false; v_criador uuid;
  v_a_cor uuid; v_a_tex uuid; v_a_med uuid; v_g_cor uuid; v_g_tex uuid; v_med_unit text;
  v_grupo uuid; v_opc uuid; v_ativa boolean; v_mod uuid; v_prefixo text; v_regex text; v_n_entra integer;
  v_auth uuid; v_claims text; v_prev jsonb; r record;
BEGIN
  -- ─── 0. Guarda (inerte) ───────────────────────────────────────────────────────
  IF NOT EXISTS (SELECT 1 FROM anew_organizations o WHERE o.id = c_org AND o.name = 'Mudelar' AND o.deleted_at IS NULL) THEN
    RAISE NOTICE 'bases_duche_mudelar: a organização Mudelar (%) não existe nesta base — nada a fazer.', c_org;
    RETURN;
  END IF;
  IF to_regclass('public.product_models') IS NULL
     OR to_regprocedure('public.fn_cat_modelo_numero(uuid,uuid,uuid)') IS NULL
     OR to_regprocedure('public.cat_prever_sku_modelo(uuid,uuid,uuid,uuid,jsonb,uuid)') IS NULL
     OR to_regprocedure('public.cat_gerar_sku_produto(uuid,uuid,boolean)') IS NULL
     OR position('fn_cat_modelo_numero' IN coalesce((SELECT pr.prosrc FROM pg_proc pr
                                                     WHERE pr.oid = to_regprocedure('public.cat_gerar_sku_produto(uuid,uuid,boolean)')::oid), '')) = 0 THEN
    RAISE NOTICE 'bases_duche_mudelar: falta a versão dos modelos (20270118300000: product_models, fn_cat_modelo_numero, cat_prever_sku_modelo) — nada a fazer.';
    RETURN;
  END IF;
  -- as funções do Catálogo que esta importação usa (estas existem na RH: se faltarem, é erro, não guarda)
  SELECT string_agg(s, ', ') INTO v_txt
  FROM unnest(ARRAY['public.fn_cat_chave_opcao(text)', 'public.fn_cat_limpar_nome(text)', 'public.fn_cat_num_texto(numeric)',
                    'public.fn_cat_grupo_do_atributo(uuid,uuid)', 'public.fn_cat_medida_ler(jsonb,text)',
                    'public.fn_cat_sku_medida(jsonb)', 'public.fn_cat_sku_partes(uuid,uuid,uuid,jsonb)',
                    'public.fn_cat_sigla_opcao_livre(uuid,text,uuid)', 'public.fn_cat_unidade(uuid,text)',
                    'public.has_anew_permission_in_org(uuid,text,uuid)',
                    'public.fn_manual_audit_log(text,uuid,uuid,text,jsonb,text,uuid)']) s
  WHERE to_regprocedure(s) IS NULL;
  IF v_txt IS NOT NULL THEN RAISE EXCEPTION 'bases_duche_mudelar: faltam funções do Catálogo (%).', v_txt; END IF;

  -- categoria e subcategoria
  SELECT count(*), (array_agg(c.id ORDER BY c.created_at, c.id))[1], (array_agg(c.sigla ORDER BY c.created_at, c.id))[1],
         (array_agg(coalesce(c.is_active, true) ORDER BY c.created_at, c.id))[1]
    INTO v_n, v_cat, v_cat_sigla, v_cat_ativa
  FROM product_categories c
  WHERE c.organization_id = c_org AND c.parent_id IS NULL AND c.deleted_at IS NULL
    AND public.fn_cat_chave_opcao(c.name) = public.fn_cat_chave_opcao(c_cat_nome);
  IF v_n = 0 THEN
    RAISE NOTICE 'bases_duche_mudelar: a Mudelar não tem a categoria «%» — nada a fazer.', c_cat_nome;
    RETURN;
  ELSIF v_n > 1 THEN
    RAISE EXCEPTION 'bases_duche_mudelar: há % categorias «%» na Mudelar.', v_n, c_cat_nome;
  END IF;
  SELECT count(*), (array_agg(c.id ORDER BY c.created_at, c.id))[1], (array_agg(c.sigla ORDER BY c.created_at, c.id))[1],
         (array_agg(coalesce(c.is_active, true) ORDER BY c.created_at, c.id))[1]
    INTO v_n, v_sub, v_sub_sigla, v_sub_ativa
  FROM product_categories c
  WHERE c.organization_id = c_org AND c.parent_id = v_cat AND c.deleted_at IS NULL
    AND public.fn_cat_chave_opcao(c.name) = public.fn_cat_chave_opcao(c_sub_nome);
  IF v_n = 0 THEN
    RAISE NOTICE 'bases_duche_mudelar: a Mudelar não tem a subcategoria «%» › «%» — nada a fazer.', c_cat_nome, c_sub_nome;
    RETURN;
  ELSIF v_n > 1 THEN
    RAISE EXCEPTION 'bases_duche_mudelar: há % subcategorias «%» em «%».', v_n, c_sub_nome, c_cat_nome;
  END IF;
  IF EXISTS (SELECT 1 FROM products p WHERE p.organization_id = c_org AND p.subcategory_id = v_sub AND NOT p.is_deleted) THEN
    RAISE NOTICE 'bases_duche_mudelar: a subcategoria «%» da Mudelar já tem produtos — nada a fazer.', c_sub_nome;
    RETURN;
  END IF;

  -- ─── Os dados do Excel (gerados) ──────────────────────────────────────────────
  DROP TABLE IF EXISTS pg_temp._bdm_linhas, pg_temp._bdm_medidas, pg_temp._bdm_modelos, pg_temp._bdm_opcoes,
                       pg_temp._bdm_deslocadas, pg_temp._bdm_attr, pg_temp._bdm;

  -- os 7 modelos: número (NNNN do SKU), nome do modelo, o nome do modelo como vem no nome do produto do Excel (o 0002 é
  -- «STONE PLUS» mas os produtos dizem «PLUS»: o nome do produto fica o do Excel), quantos produtos tem e que texturas
  CREATE TEMP TABLE _bdm_modelos (numero smallint PRIMARY KEY, nome text NOT NULL, nome_produto text NOT NULL, esperados integer NOT NULL,
                                  texturas text NOT NULL, modelo_id uuid) ON COMMIT DROP;
  INSERT INTO _bdm_modelos (numero, nome, nome_produto, esperados, texturas) VALUES
    (1, 'SORTY', 'SORTY', 1386, 'PZ'),
    (2, 'STONE PLUS', 'PLUS', 2988, 'LS,PZ'),
    (3, 'CACH', 'CACH', 1512, 'LS,PZ'),
    (4, 'MIO', 'MIO', 1386, 'LS'),
    (5, 'SIDE', 'SIDE', 2772, 'LS,PZ'),
    (6, 'SMART', 'SMART', 1512, 'LS,PZ'),
    (7, 'ZEUS', 'ZEUS', 2772, 'PD,PZ');

  -- as 18 cores e 3 texturas: código do Excel (= a sigla na Mudelar), nome no Excel, nome da opção na Mudelar
  CREATE TEMP TABLE _bdm_opcoes (papel text NOT NULL, codigo text NOT NULL, nome_excel text NOT NULL, nome_mudelar text NOT NULL,
                                 ordem integer NOT NULL, grupo uuid, opcao_id uuid, valor text, PRIMARY KEY (papel, codigo)) ON COMMIT DROP;
  INSERT INTO _bdm_opcoes (papel, codigo, nome_excel, nome_mudelar, ordem) VALUES
