    (7, 'MK', 95, 190, 'PZ'),
    (7, 'TP', 95, 190, 'PZ'),
    (7, 'CH', 95, 190, 'PZ'),
    (7, 'TC', 95, 190, 'PZ'),
    (7, 'CL', 95, 190, 'PZ'),
    (7, 'RS', 95, 190, 'PZ'),
    (7, 'TQ', 95, 190, 'PZ'),
    (7, 'OC', 95, 190, 'PZ'),
    (7, 'OL', 95, 190, 'PZ'),
    (7, 'BL', 95, 200, 'PZ'),
    (7, 'GR7', 95, 200, 'PZ'),
    (7, 'GR', 95, 200, 'PZ'),
    (7, 'GM', 95, 200, 'PZ'),
    (7, 'AN', 95, 200, 'PZ'),
    (7, 'NG', 95, 200, 'PZ'),
    (7, 'CR', 95, 200, 'PZ'),
    (7, 'BG', 95, 200, 'PZ'),
    (7, 'AR', 95, 200, 'PZ'),
    (7, 'MK', 95, 200, 'PZ'),
    (7, 'TP', 95, 200, 'PZ'),
    (7, 'CH', 95, 200, 'PZ'),
    (7, 'TC', 95, 200, 'PZ'),
    (7, 'CL', 95, 200, 'PZ'),
    (7, 'RS', 95, 200, 'PZ'),
    (7, 'TQ', 95, 200, 'PZ'),
    (7, 'OC', 95, 200, 'PZ'),
    (7, 'OL', 95, 200, 'PZ'),
    (7, 'BL', 95, 210, 'PZ'),
    (7, 'GR7', 95, 210, 'PZ'),
    (7, 'GR', 95, 210, 'PZ'),
    (7, 'GM', 95, 210, 'PZ'),
    (7, 'AN', 95, 210, 'PZ'),
    (7, 'NG', 95, 210, 'PZ'),
    (7, 'CR', 95, 210, 'PZ'),
    (7, 'BG', 95, 210, 'PZ'),
    (7, 'AR', 95, 210, 'PZ'),
    (7, 'MK', 95, 210, 'PZ'),
    (7, 'TP', 95, 210, 'PZ'),
    (7, 'CH', 95, 210, 'PZ'),
    (7, 'TC', 95, 210, 'PZ'),
    (7, 'CL', 95, 210, 'PZ'),
    (7, 'RS', 95, 210, 'PZ'),
    (7, 'TQ', 95, 210, 'PZ'),
    (7, 'OC', 95, 210, 'PZ'),
    (7, 'OL', 95, 210, 'PZ');

  -- os dados gerados estão inteiros
  SELECT count(*), count(DISTINCT (l.modelo, l.cor, l.largura, l.comprimento, l.textura)) INTO v_n, v_m FROM _bdm_linhas l;
  IF v_n <> c_total OR v_m <> c_total THEN
    RAISE EXCEPTION 'bases_duche_mudelar: os dados gerados têm % linhas (% distintas) em vez de %.', v_n, v_m, c_total;
  END IF;
  IF EXISTS (SELECT 1 FROM _bdm_linhas l
             WHERE NOT EXISTS (SELECT 1 FROM _bdm_modelos m WHERE m.numero = l.modelo)
                OR NOT EXISTS (SELECT 1 FROM _bdm_opcoes o WHERE o.papel = 'cor' AND o.codigo = l.cor)
                OR NOT EXISTS (SELECT 1 FROM _bdm_opcoes o WHERE o.papel = 'textura' AND o.codigo = l.textura)
                OR NOT EXISTS (SELECT 1 FROM _bdm_medidas d WHERE d.largura = l.largura AND d.comprimento = l.comprimento)) THEN
    RAISE EXCEPTION 'bases_duche_mudelar: há linhas com modelo, cor, textura ou medida fora das tabelas geradas.';
  END IF;
  IF (SELECT sum(m.esperados) FROM _bdm_modelos m) <> c_total THEN
    RAISE EXCEPTION 'bases_duche_mudelar: as contagens por modelo não somam %.', c_total;
  END IF;

  -- mais guardas inertes: os nomes já existem na Mudelar? modelos com o mesmo nome/número que não sejam estes?
  SELECT count(*) INTO v_n FROM products p
  WHERE p.organization_id = c_org AND NOT p.is_deleted
    AND p.name IN (SELECT 'Base de Duche ' || m.nome_produto || ' ' || oc.nome_excel || ' ' || l.largura || 'X' || l.comprimento || ' ' || ot.nome_excel
                   FROM _bdm_linhas l JOIN _bdm_modelos m ON m.numero = l.modelo
                   JOIN _bdm_opcoes oc ON oc.papel = 'cor' AND oc.codigo = l.cor
                   JOIN _bdm_opcoes ot ON ot.papel = 'textura' AND ot.codigo = l.textura);
  IF v_n > 0 THEN
    RAISE NOTICE 'bases_duche_mudelar: a Mudelar já tem % produtos vivos com nomes do Excel — nada a fazer.', v_n;
    RETURN;
  END IF;
  SELECT string_agg(pm.name || ' (' || lpad(pm.numero::text, 4, '0') || (CASE WHEN pm.deleted_at IS NOT NULL THEN ', apagado' ELSE '' END) || ')', ', ')
    INTO v_txt
  FROM product_models pm
  WHERE pm.organization_id = c_org AND pm.subcategory_id = v_sub
    AND EXISTS (SELECT 1 FROM _bdm_modelos m
                WHERE (pm.numero = m.numero OR (pm.deleted_at IS NULL AND public.fn_cat_chave_opcao(pm.name) = public.fn_cat_chave_opcao(m.nome)))
                  AND NOT (pm.numero = m.numero AND pm.deleted_at IS NULL AND public.fn_cat_chave_opcao(pm.name) = public.fn_cat_chave_opcao(m.nome)));
  IF v_txt IS NOT NULL THEN
    RAISE NOTICE 'bases_duche_mudelar: a subcategoria já tem modelos com estes nomes ou números, diferentes dos do Excel (%) — nada a fazer.', v_txt;
    RETURN;
  END IF;

  -- ─── Configuração que tem de existir (senão: erro) ───────────────────────────
  IF v_cat_sigla IS NULL OR v_sub_sigla IS NULL THEN
    RAISE EXCEPTION 'bases_duche_mudelar: «%» ou «%» não têm sigla (o SKU precisa das duas).', c_cat_nome, c_sub_nome;
  END IF;
  IF NOT v_cat_ativa OR NOT v_sub_ativa THEN
    RAISE EXCEPTION 'bases_duche_mudelar: «%» ou «%» está desativada.', c_cat_nome, c_sub_nome;
  END IF;

  -- quem fica em created_by: o membro ativo mais antigo da Mudelar (como 20270117800000 e 20270117900000)
  SELECT m.user_id INTO v_criador
  FROM anew_memberships m JOIN anew_users u ON u.id = m.user_id AND u.deleted_at IS NULL
  WHERE m.organization_id = c_org AND m.status = 'active' AND m.end_date IS NULL AND coalesce(m.role_is_client, false) = false
  ORDER BY m.created_at, m.user_id LIMIT 1;
  IF v_criador IS NULL THEN RAISE EXCEPTION 'bases_duche_mudelar: a Mudelar não tem um membro ativo para created_by.'; END IF;

  SELECT count(*), (array_agg(b.id ORDER BY b.created_at, b.id))[1], (array_agg(coalesce(b.is_active, true) ORDER BY b.created_at, b.id))[1]
    INTO v_n, v_marca, v_marca_ativa
  FROM brands b
  WHERE b.organization_id = c_org AND b.deleted_at IS NULL AND public.fn_cat_chave_opcao(b.name) = public.fn_cat_chave_opcao(c_marca_nome);
  IF v_n <> 1 THEN RAISE EXCEPTION 'bases_duche_mudelar: a Mudelar tem % marcas «%» (tem de ter uma).', v_n, c_marca_nome; END IF;
  IF NOT v_marca_ativa THEN RAISE EXCEPTION 'bases_duche_mudelar: a marca «%» está desativada.', c_marca_nome; END IF;

  -- atributos (pelo código) e os grupos de opções, que têm de ser da Mudelar (as siglas de um grupo global não se mudam)
  SELECT count(*) FILTER (WHERE a.code::text = 'cor'), count(*) FILTER (WHERE a.code::text = 'textura'), count(*) FILTER (WHERE a.code::text = 'medida'),
         (array_agg(a.id) FILTER (WHERE a.code::text = 'cor'))[1], (array_agg(a.id) FILTER (WHERE a.code::text = 'textura'))[1],
         (array_agg(a.id) FILTER (WHERE a.code::text = 'medida' AND a.is_measurement))[1],
         (array_agg(a.unit::text) FILTER (WHERE a.code::text = 'medida'))[1]
    INTO v_n, v_m, v_k, v_a_cor, v_a_tex, v_a_med, v_med_unit
  FROM product_attributes a WHERE a.organization_id = c_org AND a.deleted_at IS NULL;
  IF v_n <> 1 OR v_m <> 1 OR v_k <> 1 OR v_a_cor IS NULL OR v_a_tex IS NULL OR v_a_med IS NULL THEN
    RAISE EXCEPTION 'bases_duche_mudelar: a Mudelar tem de ter um atributo cor, um textura e uma medida (is_measurement).';
  END IF;
  IF EXISTS (SELECT 1 FROM product_attributes a WHERE a.id IN (v_a_cor, v_a_tex) AND a.is_measurement) THEN
    RAISE EXCEPTION 'bases_duche_mudelar: cor ou textura da Mudelar é uma medida.';
  END IF;
  IF coalesce(lower(v_med_unit), 'cm') <> 'cm' THEN
    RAISE EXCEPTION 'bases_duche_mudelar: a Medida da Mudelar está em «%»; as medidas do Excel são em cm.', v_med_unit;
  END IF;
  v_g_cor := public.fn_cat_grupo_do_atributo(v_a_cor, c_org);
  v_g_tex := public.fn_cat_grupo_do_atributo(v_a_tex, c_org);
  IF NOT EXISTS (SELECT 1 FROM attribute_option_groups g WHERE g.id = v_g_cor AND g.organization_id = c_org)
     OR NOT EXISTS (SELECT 1 FROM attribute_option_groups g WHERE g.id = v_g_tex AND g.organization_id = c_org) THEN
    RAISE EXCEPTION 'bases_duche_mudelar: as opções de Cor ou de Textura em uso na Mudelar não são de um grupo da Mudelar.';
  END IF;

  -- ─── Locks (as chaves das funções de gestão do Catálogo), depois a fotografia das outras organizações ─────
  PERFORM pg_advisory_xact_lock(hashtextextended('cat_marcas:' || c_org::text, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('cat_categorias_produto:' || c_org::text, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('cat_sku_config:' || c_org::text, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('cat_modelos:' || c_org::text, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('cat_modelos:' || c_org::text || ':' || v_sub::text, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('cat_sigla_opc:' || v_g_cor::text, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('cat_sigla_opc:' || v_g_tex::text, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('cat_fornecedores:' || c_org::text, 0));

  PERFORM set_config('app.audit_source', c_fonte, true);
  PERFORM set_config('app.audit_user_id', v_criador::text, true);

  -- ─── 1. Siglas das 18 cores e 3 texturas = códigos do Excel ───────────────────
  FOR r IN SELECT o.papel, o.codigo, o.nome_mudelar FROM _bdm_opcoes o ORDER BY o.papel, o.ordem LOOP
    v_grupo := (CASE WHEN r.papel = 'cor' THEN v_g_cor ELSE v_g_tex END);
    SELECT count(*), (array_agg(v.id ORDER BY v.id))[1], (array_agg(v.is_active ORDER BY v.id))[1] INTO v_n, v_opc, v_ativa
    FROM attribute_option_group_values v
    WHERE v.group_id = v_grupo AND public.fn_cat_chave_opcao(v.value_text::text) = public.fn_cat_chave_opcao(r.nome_mudelar);
    IF v_n > 1 THEN
      RAISE EXCEPTION 'bases_duche_mudelar: há % opções «%» na % da Mudelar.', v_n, r.nome_mudelar, r.papel;
    END IF;
    IF v_n = 1 AND NOT v_ativa THEN
      RAISE EXCEPTION 'bases_duche_mudelar: a opção «%» (%) da Mudelar está desativada.', r.nome_mudelar, r.papel;
    END IF;
    UPDATE _bdm_opcoes o SET grupo = v_grupo, opcao_id = v_opc WHERE o.papel = r.papel AND o.codigo = r.codigo;
  END LOOP;

  -- quem já tem um dos códigos e não é a opção do Excel fica, por agora, sem sigla
  CREATE TEMP TABLE _bdm_deslocadas ON COMMIT DROP AS
  SELECT v.id, v.group_id, coalesce(v.display_name, v.value_text)::text AS nome, v.sigla AS sigla_antes, coalesce(v.sort_order, 0) AS ordem
  FROM attribute_option_group_values v JOIN _bdm_opcoes o ON o.grupo = v.group_id AND v.sigla = o.codigo
  WHERE v.id IS DISTINCT FROM o.opcao_id
    AND NOT EXISTS (SELECT 1 FROM _bdm_opcoes o2 WHERE o2.opcao_id = v.id);  -- uma opção do Excel recebe o seu código, não uma sugestão
  UPDATE attribute_option_group_values v SET sigla = NULL FROM _bdm_deslocadas d WHERE v.id = d.id;
  -- as opções do Excel: primeiro sem sigla, depois o código (sem colisões passageiras entre elas)
  UPDATE attribute_option_group_values v SET sigla = NULL FROM _bdm_opcoes o WHERE v.id = o.opcao_id AND v.sigla IS DISTINCT FROM o.codigo;
  UPDATE attribute_option_group_values v SET sigla = o.codigo FROM _bdm_opcoes o WHERE v.id = o.opcao_id AND v.sigla IS DISTINCT FROM o.codigo;
  -- as que faltarem criam-se no grupo da Mudelar, com a sigla do Excel e sem hex
  FOR r IN SELECT o.papel, o.codigo, o.nome_excel, o.grupo FROM _bdm_opcoes o WHERE o.opcao_id IS NULL ORDER BY o.papel, o.ordem LOOP
    INSERT INTO attribute_option_group_values (group_id, value_text, display_name, hex_color, sort_order, is_active, sigla)
    VALUES (r.grupo, r.nome_excel, r.nome_excel, NULL,
            coalesce((SELECT max(v.sort_order) FROM attribute_option_group_values v WHERE v.group_id = r.grupo), 0) + 1, true, r.codigo)
    RETURNING id INTO v_opc;
    UPDATE _bdm_opcoes o SET opcao_id = v_opc WHERE o.papel = r.papel AND o.codigo = r.codigo;
    v_criadas := v_criadas || r.nome_excel || ' (' || r.codigo || '); ';
  END LOOP;
  UPDATE _bdm_opcoes o SET valor = v.value_text::text FROM attribute_option_group_values v WHERE v.id = o.opcao_id;
  -- as deslocadas recebem a sugestão seguinte, uma a uma (cada uma vê as já escolhidas)
  FOR r IN SELECT d.id, d.group_id, d.nome, d.sigla_antes FROM _bdm_deslocadas d ORDER BY d.group_id, d.ordem, d.nome, d.id LOOP
    v_txt := public.fn_cat_sigla_opcao_livre(r.group_id, r.nome, r.id);
    IF v_txt IS NULL THEN RAISE EXCEPTION 'bases_duche_mudelar: sem sigla livre para a opção «%».', r.nome; END IF;
    UPDATE attribute_option_group_values v SET sigla = v_txt WHERE v.id = r.id;
    v_trocas := v_trocas || r.nome || ' ' || r.sigla_antes || '→' || v_txt || '; ';
  END LOOP;

  -- ─── 2. Os 7 modelos na subcategoria (números 1..7) ───────────────────────────
  SELECT count(*) FILTER (WHERE pm.is_active), count(*) INTO v_n, v_m
  FROM product_models pm WHERE pm.organization_id = c_org AND pm.deleted_at IS NULL;
  IF v_n + 7 > c_max_modelos_ativos OR v_m + 7 > c_max_modelos_vivos THEN
    RAISE EXCEPTION 'bases_duche_mudelar: a Mudelar passaria o teto de modelos (% ativos, % vivos).', v_n, v_m;
  END IF;
  FOR r IN SELECT m.numero, m.nome FROM _bdm_modelos m ORDER BY m.numero LOOP
    v_mod := NULL;
    SELECT pm.id, pm.is_active INTO v_mod, v_ativa FROM product_models pm
    WHERE pm.organization_id = c_org AND pm.subcategory_id = v_sub AND pm.numero = r.numero AND pm.deleted_at IS NULL
      AND public.fn_cat_chave_opcao(pm.name) = public.fn_cat_chave_opcao(r.nome);
    IF v_mod IS NOT NULL AND NOT v_ativa THEN
      RAISE EXCEPTION 'bases_duche_mudelar: o modelo % (%) já existe e está desativado.', r.nome, lpad(r.numero::text, 4, '0');
    END IF;
    IF v_mod IS NULL THEN
      INSERT INTO product_models (organization_id, subcategory_id, name, numero, is_active, created_by)
      VALUES (c_org, v_sub, r.nome, r.numero, true, v_criador)
      RETURNING id INTO v_mod;
    END IF;
    UPDATE _bdm_modelos m SET modelo_id = v_mod WHERE m.numero = r.numero;
  END LOOP;

  -- ─── 3. Unidade «un» e fornecedor ─────────────────────────────────────────────
  -- a de cat_guardar_produto_tabelas: encontra a global ou a da Mudelar; cria-a na Mudelar se não houver (lido a 16/11: não há)
  v_uom := public.fn_cat_unidade(c_org, c_unidade);
  IF v_uom IS NULL THEN RAISE EXCEPTION 'bases_duche_mudelar: sem unidade «%».', c_unidade; END IF;

  SELECT s.id, coalesce(s.is_active, true) INTO v_sup, v_sup_ativo FROM suppliers s
  WHERE s.organization_id = c_org AND s.deleted_at IS NULL
    AND public.fn_cat_chave_opcao(s.name) = public.fn_cat_chave_opcao(c_forn_nome)
  ORDER BY s.created_at, s.id LIMIT 1;
  IF v_sup IS NOT NULL AND NOT v_sup_ativo THEN
    RAISE EXCEPTION 'bases_duche_mudelar: o fornecedor «%» da Mudelar está desativado.', c_forn_nome;
  END IF;
  IF v_sup IS NULL THEN
    -- o insert do ecrã de Fornecedores (como 20270101270000 e cat_ligar_fornecedor_produto, sem NIF nem email)
    INSERT INTO suppliers (organization_id, name, is_active, created_by)
    VALUES (c_org, public.fn_cat_limpar_nome(c_forn_nome), true, v_criador)
    RETURNING id INTO v_sup;
    v_sup_criado := true;
  END IF;

  -- ─── 4. As linhas a gravar, com o SKU final (a regra de fn_cat_sku_partes, set-based) ──────────
  UPDATE _bdm_medidas d SET seg = public.fn_cat_sku_medida(jsonb_build_object('tipo', '2D', 'largura', d.largura::numeric,
                                                                              'comprimento', d.comprimento::numeric, 'unidade', 'cm'));
  IF EXISTS (SELECT 1 FROM _bdm_medidas d WHERE d.seg IS NULL) THEN
    RAISE EXCEPTION 'bases_duche_mudelar: há medidas inválidas para o SKU.';
  END IF;

  CREATE TEMP TABLE _bdm_attr (id uuid PRIMARY KEY, papel text NOT NULL, sku_ordem integer, ordem integer NOT NULL, nome text NOT NULL,
                               entra boolean NOT NULL) ON COMMIT DROP;
  INSERT INTO _bdm_attr (id, papel, sku_ordem, ordem, nome, entra)
  SELECT a.id, x.papel, a.sku_ordem, coalesce(a.sort_order, 0), a.label::text, a.sku_entra
  FROM (VALUES ('cor', v_a_cor), ('textura', v_a_tex), ('medida', v_a_med)) AS x(papel, id)
  JOIN product_attributes a ON a.id = x.id;
  v_n_entra := (SELECT count(*) FROM _bdm_attr a WHERE a.entra);
  v_prefixo := concat_ws('-', v_cat_sigla, v_sub_sigla);

  CREATE TEMP TABLE _bdm ON COMMIT DROP AS
  SELECT gen_random_uuid() AS id, l.linha, l.modelo, m.modelo_id, l.cor, oc.valor AS cor_valor, oc.opcao_id AS cor_opcao,
         l.textura, ot.valor AS tex_valor, ot.opcao_id AS tex_opcao, l.largura, l.comprimento, d.custo, d.pvp, d.seg AS med_seg,
         'Base de Duche ' || m.nome_produto || ' ' || oc.nome_excel || ' ' || l.largura || 'X' || l.comprimento || ' ' || ot.nome_excel AS nome,
         NULL::text AS sku
  FROM _bdm_linhas l
  JOIN _bdm_modelos m ON m.numero = l.modelo
  JOIN _bdm_opcoes oc ON oc.papel = 'cor' AND oc.codigo = l.cor
  JOIN _bdm_opcoes ot ON ot.papel = 'textura' AND ot.codigo = l.textura
  JOIN _bdm_medidas d ON d.largura = l.largura AND d.comprimento = l.comprimento;
  SELECT count(*) INTO v_n FROM _bdm;
  IF v_n <> c_total THEN RAISE EXCEPTION 'bases_duche_mudelar: % linhas a gravar em vez de %.', v_n, c_total; END IF;

  -- CAT-SUB-NNNN-<um segmento por atributo que entra, por sku_ordem NULLS LAST, sort_order, nome, id>; a sigla da opção = o código
  UPDATE _bdm b SET sku = concat_ws('-', v_prefixo, lpad(b.modelo::text, 4, '0'),
    (SELECT nullif(string_agg(s.seg, '-' ORDER BY a.sku_ordem NULLS LAST, a.ordem, a.nome, a.id) FILTER (WHERE a.entra AND s.seg IS NOT NULL), '')
     FROM (VALUES ('cor', b.cor), ('textura', b.textura), ('medida', b.med_seg)) AS s(papel, seg)
     JOIN _bdm_attr a ON a.papel = s.papel));

  -- SKU repetido entre as linhas (o mesmo produto duas vezes): para e diz quais
  SELECT string_agg(x.sku || ' ×' || x.n || ' (' || x.nomes || ')', '; ') INTO v_txt
  FROM (SELECT b.sku, count(*) AS n, string_agg(b.nome, ' | ' ORDER BY b.linha) AS nomes FROM _bdm b
        GROUP BY b.sku HAVING count(*) > 1 ORDER BY b.sku LIMIT 10) x;
  IF v_txt IS NOT NULL THEN RAISE EXCEPTION 'bases_duche_mudelar: SKUs repetidos: %', v_txt; END IF;
  -- já usado por outro produto da Mudelar (vivo ou apagado: products_sku_organization_id_key cobre os dois)
  SELECT string_agg(b.sku || ' (' || p.name || ')', '; ') INTO v_txt
  FROM (SELECT b2.sku FROM _bdm b2 JOIN products p2 ON p2.organization_id = c_org AND p2.sku = b2.sku ORDER BY b2.sku LIMIT 10) b
  JOIN products p ON p.organization_id = c_org AND p.sku = b.sku;
  IF v_txt IS NOT NULL THEN RAISE EXCEPTION 'bases_duche_mudelar: SKUs já usados noutros produtos da Mudelar: %', v_txt; END IF;
  v_regex := '^' || v_prefixo || '-[0-9]{4}' || repeat('-[A-Z0-9]+', v_n_entra) || '$';
  IF EXISTS (SELECT 1 FROM _bdm b WHERE b.sku !~ v_regex) THEN
    RAISE EXCEPTION 'bases_duche_mudelar: SKU fora do formato (ex.: %).', (SELECT b.sku FROM _bdm b WHERE b.sku !~ v_regex LIMIT 1);
  END IF;

  -- ─── 5. Gravar (auditoria por linha desligada: fica uma linha consolidada no fim) ───────────────
  PERFORM set_config('app.audit_bypass', 'on', true);

  -- como cat_guardar_produto: ativo, vendável (produto), comprável, sem variantes, gere stock; o gatilho
  -- trg_cat_produto_tabelas preenche marca_livre, unidade e catalogo_categoria_id a partir dos ids
  INSERT INTO products (id, organization_id, sku, name, status, is_active, is_sellable, is_purchasable, has_variants, is_deleted,
                        manages_stock, created_by, tipo_catalogo, category_id, subcategory_id, model_id, brand_id, uom_id,
                        supplier_id, fornecedor_livre, sku_gerado)
  SELECT b.id, c_org, b.sku, b.nome, 'active'::product_status, true, true, true, false, false,
         true, v_criador, 'produto', v_cat, v_sub, b.modelo_id, v_marca, v_uom,
         v_sup, public.fn_cat_limpar_nome(c_forn_nome), true
  FROM _bdm b ORDER BY b.linha;

  INSERT INTO product_organizations (product_id, organization_id, created_by)
  SELECT b.id, c_org, v_criador FROM _bdm b ORDER BY b.linha;

  -- custo (preco_exato a 6 casas, price a 2) e PVP; o PVP 1 µs depois (product_prices_product_id_currency_valid_from_key),
  -- como fn_cat_depois_do_ultimo_preco
  INSERT INTO product_prices (product_id, currency, price, preco_exato, valid_from, created_by, price_type, vat_rate)
  SELECT b.id, 'EUR'::currency_code, round(b.custo, 2), round(b.custo, 6), v_agora, v_criador, 'purchase'::price_type, c_iva
  FROM _bdm b
  UNION ALL
  SELECT b.id, 'EUR'::currency_code, round(b.pvp, 2), NULL::numeric, v_agora + interval '1 microsecond', v_criador, 'retail'::price_type, c_iva
  FROM _bdm b;

  -- como cat_guardar_produto_atributos: opção = value_text da opção; medida = «70 × 70 cm» e value_json 2D em cm
  INSERT INTO product_attribute_values (product_id, attribute_id, value_text, value_json, unit)
  SELECT b.id, v_a_cor, b.cor_valor, NULL::jsonb, NULL::text FROM _bdm b
  UNION ALL
  SELECT b.id, v_a_tex, b.tex_valor, NULL::jsonb, NULL::text FROM _bdm b
  UNION ALL
  SELECT b.id, v_a_med,
         public.fn_cat_num_texto(b.largura::numeric) || ' × ' || public.fn_cat_num_texto(b.comprimento::numeric) || ' cm',
         jsonb_build_object('tipo', '2D', 'largura', b.largura::numeric, 'comprimento', b.comprimento::numeric, 'espessura', NULL, 'unidade', 'cm'),
         'cm'
  FROM _bdm b;

  -- como cat_ligar_fornecedor_produto: preferido, unidade do produto, supplier_sku = SKU, preço = custo, preco_data = hoje
  INSERT INTO item_suppliers (organization_id, item_type, product_id, supplier_id, uom_id, supplier_sku, purchase_price, currency,
                              is_preferred, is_active, created_by, preco_data)
  SELECT c_org, 'product', b.id, v_sup, NULL, b.sku, round(b.custo, 2), 'EUR', true, true, v_criador, current_date
  FROM _bdm b ORDER BY b.linha;

  PERFORM set_config('app.audit_bypass', 'off', true);
  PERFORM public.fn_manual_audit_log('products', v_sub, c_org, 'INSERT',
    jsonb_build_object('importacao', 'bases_duche_mudelar', 'produtos', c_total, 'modelos', 7, 'subcategoria', v_sub,
                       'fornecedor', v_sup, 'fornecedor_criado', v_sup_criado, 'unidade', v_uom,
                       'siglas_trocadas', v_trocas, 'opcoes_criadas', v_criadas),
    c_fonte, v_sub);
  IF NOT EXISTS (SELECT 1 FROM entity_audit_log e WHERE e.organization_id = c_org AND e.source = c_fonte
                 AND e.table_name = 'products' AND e.created_at >= now()) THEN
    RAISE WARNING 'bases_duche_mudelar: a linha consolidada da auditoria não ficou gravada (fn_manual_audit_log engole o erro).';
  END IF;

  -- ─── 6. Conferir ──────────────────────────────────────────────────────────────
  -- quantos, por modelo
  SELECT count(*) INTO v_n FROM products p WHERE p.organization_id = c_org AND p.subcategory_id = v_sub AND NOT p.is_deleted;
  IF v_n <> c_total THEN RAISE EXCEPTION 'Conferir: % produtos na subcategoria em vez de %.', v_n, c_total; END IF;
  SELECT string_agg(m.nome || ' ' || coalesce(x.n, 0) || ' em vez de ' || m.esperados, '; ') INTO v_txt
  FROM _bdm_modelos m
  LEFT JOIN (SELECT p.model_id, count(*) AS n FROM products p
             WHERE p.organization_id = c_org AND p.subcategory_id = v_sub AND NOT p.is_deleted GROUP BY p.model_id) x ON x.model_id = m.modelo_id
  WHERE coalesce(x.n, 0) <> m.esperados;
  IF v_txt IS NOT NULL THEN RAISE EXCEPTION 'Conferir: contagem por modelo errada: %', v_txt; END IF;
  SELECT count(*) INTO v_n FROM product_models pm JOIN _bdm_modelos m ON m.modelo_id = pm.id
  WHERE pm.organization_id = c_org AND pm.subcategory_id = v_sub AND pm.deleted_at IS NULL AND pm.is_active
    AND pm.numero = m.numero AND pm.name = m.nome;
  IF v_n <> 7 THEN RAISE EXCEPTION 'Conferir: % modelos certos em vez de 7.', v_n; END IF;

  -- cada produto tal como a linha do Excel: nome, SKU, modelo, marca, unidade, categoria, fornecedor, preços, atributos
  SELECT count(*) INTO v_n
  FROM _bdm b
  JOIN products p ON p.id = b.id
  LEFT JOIN product_attribute_values vc ON vc.product_id = b.id AND vc.attribute_id = v_a_cor
  LEFT JOIN product_attribute_values vt ON vt.product_id = b.id AND vt.attribute_id = v_a_tex
  LEFT JOIN product_attribute_values vm ON vm.product_id = b.id AND vm.attribute_id = v_a_med
  LEFT JOIN product_prices pc ON pc.product_id = b.id AND pc.price_type = 'purchase'
  LEFT JOIN product_prices pv ON pv.product_id = b.id AND pv.price_type = 'retail'
  LEFT JOIN item_suppliers i ON i.product_id = b.id AND i.deleted_at IS NULL
  WHERE NOT coalesce(p.organization_id = c_org AND p.name = b.nome AND p.sku = b.sku AND p.sku_gerado AND p.model_id = b.modelo_id
        AND p.category_id = v_cat AND p.subcategory_id = v_sub AND p.brand_id = v_marca AND p.marca_livre = c_marca_nome
        AND p.uom_id = v_uom AND p.unidade = c_unidade AND p.status = 'active'::product_status AND p.tipo_catalogo = 'produto'
        AND p.manages_stock AND p.is_active AND NOT p.is_deleted AND p.supplier_id = v_sup
        AND p.fornecedor_livre = public.fn_cat_limpar_nome(c_forn_nome)
        AND vc.value_text = b.cor_valor AND vt.value_text = b.tex_valor
        AND vm.value_json = jsonb_build_object('tipo', '2D', 'largura', b.largura, 'comprimento', b.comprimento, 'espessura', NULL, 'unidade', 'cm')
        AND vm.unit = 'cm' AND public.fn_cat_medida_ler(vm.value_json, vm.unit) IS NOT NULL
        AND pc.price = round(b.custo, 2) AND pc.preco_exato = round(b.custo, 6) AND pc.vat_rate = c_iva
        AND pv.price = round(b.pvp, 2) AND pv.vat_rate = c_iva
        AND i.supplier_id = v_sup AND i.is_preferred AND i.is_active AND i.purchase_price = round(b.custo, 2) AND i.supplier_sku = p.sku,
        false);
  IF v_n > 0 THEN RAISE EXCEPTION 'Conferir: % produtos não ficaram como a linha do Excel.', v_n; END IF;
  -- nem linhas a mais: 3 valores, 2 preços, 1 fornecedor e 1 product_organizations por produto
  SELECT (SELECT count(*) FROM product_attribute_values v JOIN _bdm b ON b.id = v.product_id),
         (SELECT count(*) FROM product_prices x JOIN _bdm b ON b.id = x.product_id)
    INTO v_n, v_m;
  IF v_n <> 3 * c_total OR v_m <> 2 * c_total THEN
    RAISE EXCEPTION 'Conferir: % valores de atributos (esperados %) e % preços (esperados %).', v_n, 3 * c_total, v_m, 2 * c_total;
  END IF;
  SELECT (SELECT count(*) FROM item_suppliers x JOIN _bdm b ON b.id = x.product_id),
         (SELECT count(*) FROM product_organizations x JOIN _bdm b ON b.id = x.product_id)
    INTO v_n, v_m;
  IF v_n <> c_total OR v_m <> c_total THEN
    RAISE EXCEPTION 'Conferir: % ligações a fornecedor e % product_organizations (esperados %).', v_n, v_m, c_total;
  END IF;

  -- SKUs: únicos, no formato, e iguais ao que cat_gerar_sku_produto calcula a partir do que ficou gravado (todos)
  SELECT count(*), count(DISTINCT p.sku), count(*) FILTER (WHERE p.sku !~ v_regex) INTO v_n, v_m, v_k
  FROM products p WHERE p.organization_id = c_org AND p.subcategory_id = v_sub AND NOT p.is_deleted;
  IF v_m <> c_total OR v_n <> c_total THEN RAISE EXCEPTION 'Conferir: SKUs não únicos (% distintos em %).', v_m, v_n; END IF;
  IF v_k > 0 THEN RAISE EXCEPTION 'Conferir: % SKUs fora do formato %.', v_k, v_regex; END IF;
  SELECT count(*), string_agg(y.sku || ' ≠ ' || coalesce(y.calc, 'null'), '; ') FILTER (WHERE y.k <= 5) INTO v_n, v_txt
  FROM (SELECT x.sku, x.calc, row_number() OVER (ORDER BY x.sku) AS k FROM (
          SELECT p.sku, pt ->> 'faltas' AS faltas, (pt ->> 'prefixo') AS prefixo,
                 concat_ws('-', pt ->> 'prefixo', lpad(public.fn_cat_modelo_numero(c_org, p.subcategory_id, p.model_id)::text, 4, '0'),
                           pt ->> 'resto') AS calc
          FROM products p
          CROSS JOIN LATERAL (SELECT public.fn_cat_sku_partes(c_org, p.category_id, p.subcategory_id, (
              SELECT coalesce(jsonb_agg(jsonb_build_object(
                       'atributo', v.attribute_id, 'sigla', o.sigla,
                       'medida', (CASE WHEN a.is_measurement THEN public.fn_cat_medida_ler(v.value_json, v.unit) END))), '[]'::jsonb)
              FROM product_attribute_values v
              JOIN product_attributes a ON a.id = v.attribute_id AND a.organization_id = c_org AND a.deleted_at IS NULL
              LEFT JOIN attribute_option_group_values o
                ON NOT a.is_measurement AND o.group_id = public.fn_cat_grupo_do_atributo(a.id, c_org) AND o.value_text = v.value_text
              WHERE v.product_id = p.id)) AS pt) z
          WHERE p.organization_id = c_org AND p.subcategory_id = v_sub AND NOT p.is_deleted) x
        WHERE x.calc IS DISTINCT FROM x.sku OR x.prefixo IS NULL OR x.faltas <> '[]') y;
  IF v_n > 0 THEN RAISE EXCEPTION 'Conferir: % SKUs diferentes do recalculado pela regra do Catálogo (ex.: %).', v_n, v_txt; END IF;

  -- 20 ao acaso com cat_prever_sku_modelo, como um membro da Mudelar com products.edit (só leitura; claims locais)
  SELECT u.auth_user_id INTO v_auth
  FROM anew_memberships m JOIN anew_users u ON u.id = m.user_id AND u.deleted_at IS NULL AND u.auth_user_id IS NOT NULL
  WHERE m.organization_id = c_org AND m.status = 'active' AND m.end_date IS NULL AND NOT coalesce(m.role_is_client, false)
    AND public.has_anew_permission_in_org(u.auth_user_id, 'products.edit', c_org)
  ORDER BY m.created_at, u.id LIMIT 1;
  IF v_auth IS NULL THEN
    RAISE NOTICE 'bases_duche_mudelar: sem membro da Mudelar com products.edit — a comparação com cat_prever_sku_modelo ficou por fazer (o recálculo de todos foi feito).';
  ELSE
    v_claims := current_setting('request.jwt.claims', true);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_auth, 'role', 'authenticated')::text, true);
    v_n := 0;
    FOR r IN SELECT b.id, b.sku, p.category_id, p.subcategory_id, p.model_id, b.cor_opcao, b.tex_opcao, vm.value_json
             FROM _bdm b JOIN products p ON p.id = b.id
             JOIN product_attribute_values vm ON vm.product_id = b.id AND vm.attribute_id = v_a_med
             ORDER BY random() LIMIT c_amostra LOOP
      v_prev := public.cat_prever_sku_modelo(c_org, r.category_id, r.subcategory_id, r.model_id,
                  jsonb_build_array(jsonb_build_object('atributo', v_a_cor, 'opcao', r.cor_opcao),
                                    jsonb_build_object('atributo', v_a_tex, 'opcao', r.tex_opcao),
                                    jsonb_build_object('atributo', v_a_med, 'medida', r.value_json)), r.id);
      IF (v_prev ->> 'sku') IS DISTINCT FROM r.sku OR coalesce(v_prev -> 'faltas', '[]'::jsonb) <> '[]'::jsonb THEN
        RAISE EXCEPTION 'Conferir: cat_prever_sku_modelo dá % para o produto com o SKU %.', v_prev, r.sku;
      END IF;
      v_n := v_n + 1;
    END LOOP;
    PERFORM set_config('request.jwt.claims', coalesce(v_claims, ''), true);
    IF v_n <> c_amostra THEN RAISE EXCEPTION 'Conferir: só % de % comparados com cat_prever_sku_modelo.', v_n, c_amostra; END IF;
  END IF;

  -- as 21 siglas
  SELECT count(*) INTO v_n FROM _bdm_opcoes o JOIN attribute_option_group_values v ON v.id = o.opcao_id AND v.group_id = o.grupo
  WHERE v.sigla = o.codigo AND v.is_active;
  IF v_n <> (SELECT count(*) FROM _bdm_opcoes) THEN RAISE EXCEPTION 'Conferir: só % das % siglas ficaram com o código do Excel.', v_n, (SELECT count(*) FROM _bdm_opcoes); END IF;

  -- nada foi escrito fora da Mudelar: nenhuma linha de outra organização tem o xmin desta transação (uma linha inserida
  -- ou alterada aqui teria). Mais forte do que contar antes/depois, e não falha por causa de quem estiver a trabalhar
  -- na nike durante o push (as contagens mudariam sem esta migration ter culpa).
  v_xid := (txid_current() % 4294967296)::text;
  SELECT string_agg(x.t || ' ' || x.n, ', ') INTO v_txt FROM (
    SELECT 'products' AS t, count(*) AS n FROM products p WHERE p.xmin::text = v_xid AND p.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'product_prices', count(*) FROM product_prices x JOIN products p ON p.id = x.product_id
              WHERE x.xmin::text = v_xid AND p.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'product_attribute_values', count(*) FROM product_attribute_values x JOIN products p ON p.id = x.product_id
              WHERE x.xmin::text = v_xid AND p.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'product_organizations', count(*) FROM product_organizations x WHERE x.xmin::text = v_xid AND x.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'item_suppliers', count(*) FROM item_suppliers x WHERE x.xmin::text = v_xid AND x.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'suppliers', count(*) FROM suppliers x WHERE x.xmin::text = v_xid AND x.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'product_models', count(*) FROM product_models x WHERE x.xmin::text = v_xid AND x.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'uom', count(*) FROM uom x WHERE x.xmin::text = v_xid AND x.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'brands', count(*) FROM brands x WHERE x.xmin::text = v_xid AND x.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'product_categories', count(*) FROM product_categories x WHERE x.xmin::text = v_xid AND x.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'product_attributes', count(*) FROM product_attributes x WHERE x.xmin::text = v_xid AND x.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'attribute_option_groups', count(*) FROM attribute_option_groups x WHERE x.xmin::text = v_xid AND x.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'attribute_option_group_values', count(*) FROM attribute_option_group_values v JOIN attribute_option_groups g ON g.id = v.group_id
              WHERE v.xmin::text = v_xid AND g.organization_id IS DISTINCT FROM c_org) x
  WHERE x.n > 0;
  IF v_txt IS NOT NULL THEN RAISE EXCEPTION 'Conferir: foram escritas linhas fora da Mudelar: %', v_txt; END IF;
  -- e a própria importação escreveu na transação de topo (senão a verificação acima não provava nada)
  IF NOT EXISTS (SELECT 1 FROM products p WHERE p.organization_id = c_org AND p.subcategory_id = v_sub AND p.xmin::text = v_xid) THEN
    RAISE EXCEPTION 'Conferir: os produtos importados não têm o xmin desta transação: a verificação de «nada fora da Mudelar» não vale.';
  END IF;

  RAISE NOTICE 'bases_duche_mudelar: % produtos em «%» › «%» (7 modelos, SKU %-NNNN-…), fornecedor % (%), unidade %. Siglas trocadas: %. Opções criadas: %. Conferido.',
    c_total, c_cat_nome, c_sub_nome, v_prefixo, c_forn_nome, (CASE WHEN v_sup_criado THEN 'criado' ELSE 'já existia' END), c_unidade,
    coalesce(nullif(v_trocas, ''), 'nenhuma'), coalesce(nullif(v_criadas, ''), 'nenhuma');
END $mig$;

RESET statement_timeout;
RESET lock_timeout;
